import csv, collections

for client in ["alpha","beta"]:
    visits = list(csv.DictReader(open(f"raw/{client}/visits.csv")))
    sales = list(csv.DictReader(open(f"raw/{client}/sales.csv")))
    persons = list(csv.DictReader(open(f"raw/{client}/persons.csv")))
    pid_home = {p["id"]: p["club_id"] for p in persons}

    clubs_per_person_visits = collections.defaultdict(set)
    for v in visits:
        clubs_per_person_visits[v["person_id"]].add(v["club_id"])
    multi_club_visitors = {p:c for p,c in clubs_per_person_visits.items() if len(c) > 1}

    sale_club_mismatch = 0
    for s in sales:
        pid = s["person_id"]
        if pid and pid in pid_home and s["club_id"] != pid_home[pid]:
            sale_club_mismatch += 1

    print(client, "persons:", len(persons), "multi-club visitors:", len(multi_club_visitors),
          "sale club != home club count:", sale_club_mismatch, "/", len(sales))
    if multi_club_visitors:
        ex = list(multi_club_visitors.items())[:3]
        print("  examples:", ex)
EOF

