import csv

for client in ["alpha", "beta"]:
    visits = list(csv.DictReader(open("raw/" + client + "/visits.csv")))
    persons = list(csv.DictReader(open("raw/" + client + "/persons.csv")))
    pid_home = {}
    for p in persons:
        pid_home[p["id"]] = p["club_id"]

    mismatches = 0
    missing = 0
    for v in visits:
        pid = v["person_id"]
        if pid not in pid_home:
            missing += 1
            continue
        if pid_home[pid] != v["club_id"]:
            mismatches += 1
    print(client, "visits:", len(visits), "missing person record:", missing, "club mismatch (visit vs person home):", mismatches)

